"""Registrar leituras e inspeção visual do lote B3-02 (registro 126)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==12
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,13))-{2,3,4,5},same
notes={1:'Abertura das dúvidas, troca do Emanador e compras repetidas.',2:'Cortina com a ressalva sobre Haru, Traje e Sem Técnica.',3:'Armazenamento e quadro do acordo; abertura da mescla na mesma página.',4:'Pulso de remendo e quadro das duas Classes; exemplo de Ampliação.',5:'Troca de Forma com quadro de conferência; Forma Fluida e limites.',6:'Fim da mescla; abertura de Repetir Melhorias e quadro de Firmeza.',7:'Limites da repetição, combinar efeitos e quadro da Condicional.',8:'Montagem da Lâmina e quadro da Matriz de chão.',9:'Fim da Matriz, revisão de Restrições; abertura do cancelamento no pé da página.',10:'Luz de Oficina com quadro e passagem para o combate.',11:'Desarma o Feitiço com quadro; cancelar com e sem Classe.',12:'Quadro dos limites da proposta e o que Desarma não cancela.'}
save('revisao-final.json',{'registro':126,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; pente fino.'}],'ajuste_de_diagramacao':'Casos seguem na mesma página; quadros a partir de cinco linhas podem continuar com cabeçalho repetido.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i in (2,3,4,5) else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','O caso de cancelamento começa no pé da página 9; reavaliar na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s033':[1,3],'s093':[3,6],'s094':[6,9],'s095':[9,12]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':126,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':126,'lote':'B3-02','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':41,'casos_pendentes':18,'lotes_pendentes':4,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B4-01','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
